    for ax in axes:ax.spines[['top','right']].set_visible(False);ax.grid(axis='x' if ax==axes[0] else 'y',alpha=.15);ax.set_axisbelow(True)
    fig.suptitle('Revisión de capitales pendientes: no se aplica ninguna corrección',fontsize=16)
    fig.tight_layout();fig.savefig(out/'figures/cohort.png',dpi=160,bbox_inches='tight');plt.close(fig)
    pids=['C00131038','B00723804','B19256617','B40325888','C67134620','C02948658']
